343: function median(values: readonly number[]): number {
344:   const sorted = [...values].sort((a, b) => a - b);
345:   const mid = Math.floor(sorted.length / 2);
346:   if (sorted.length % 2 === 1) return sorted[mid];
347:   return (sorted[mid - 1] + sorted[mid]) / 2;
