83: function publishSamples(samples: readonly unknown[]): void {
84:   const parsed = sampleBatchSchema.parse(samples);
85:   publishToWindows(SAMPLE_CHANNEL, parsed);
86:   // Only batches already committed to the session file can trigger the coach.
87:   const message = coach?.ingest(parsed);
88:   if (message) publishToWindows(COACH_MESSAGE_CHANNEL, coachMessageSchema.parse(message));
89: }
