94:   const parsed = validationMessageSchema.parse(message);
95:   if (parsed.code !== lastValidationCode) {
96:     lastValidationCode = parsed.code;
97:     log(`[chesspulse] sensing hint ${parsed.code}: ${parsed.hint}`);
98:   }
99:   publishToWindows(VALIDATION_CHANNEL, parsed);
