107:   const parsed = sdkErrorSchema.parse(error);
108:   // The page shows this; the terminal keeps the code so a failure can be diagnosed after the fact.
109:   logError(`[chesspulse] sensing error ${parsed.code}: ${parsed.message} (retryable=${parsed.retryable})`);
110:   publishToWindows(SDK_ERROR_CHANNEL, parsed);
