113: /** The camera is released before the session closes, so the last batch still has a session to land in. */
114: async function stopCapture(): Promise<void> {
115:   const current = capture;
116:   capture = null;
117:   coach = null;
118:   lastValidationCode = null;
119:   if (!current) return;
120:   try {
121:     await current.stop();
122:   } catch {
123:     // Best effort. Samples already written stay valid; crash recovery closes the header.
124:   }
125: }
