127: /**
128:  * Releases the camera, then closes the header. The page, consent withdrawal, the window closing
129:  * and quitting all share one promise: nobody proceeds while the native teardown is still draining,
130:  * and the session is never finalized twice.
131:  */
132: function stopEverything(reason: SessionStopReason): Promise<SessionMeta> {
133:   if (stoppingSession) return stoppingSession;
134:   const run = (async () => {
135:     await stopCapture();
136:     const meta = await stopSession(defaultDataRoot(), currentAnchor(), reason);
137:     if (reason === 'storage' || reason === 'limit') {
138:       publishToWindows(
139:         SESSION_ENDED_CHANNEL,
140:         sessionEndedSchema.parse({
141:           sessionId: meta.id,
142:           reason,
143:           message: SESSION_ENDED_COPY[reason],
144:         }),
145:       );
146:     }
147:     return meta;
148:   })();
149:   stoppingSession = run.finally(() => {
150:     stoppingSession = null;
151:   });
152:   return stoppingSession;
153: }
