163: function registerSessionHandlers(): void {
164:   ipcMain.handle(SESSION_START_CHANNEL, async (_event, payload: unknown) => {
165:     if (!currentConsent()) throw new Error('The camera stays off until you consent.');
166:     const parsed = sessionStartRequestSchema.safeParse(payload);
167:     if (!parsed.success) throw new Error('Choose a time control before starting.');
168:     if (capture) throw new Error('A session is already running.');
169:     // A previous stop may still be draining the camera; the SDK is process-global.
170:     if (stoppingSession) await stoppingSession.catch(() => undefined);
171:     const apiKey = readSensingKey(process.env);
172:     if (!apiKey) throw new Error('The SmartSpectra key is missing. Add SMARTSPECTRA_API_KEY to .env.');
173:     const anchor = currentAnchor();
174:     lastValidationCode = null;
175:     const meta = await startSession(defaultDataRoot(), anchor, parsed.data.timeControl, {
176:       onLimit: () => {
177:         void stopEverything('limit').catch(() => undefined);
178:       },
179:     });
180:     coach = new BetweenGamesCoach(meta.startAnchor.monoUs);
181:     // Consent can be withdrawn while the header is written. Checked again immediately before the
182:     // camera opens, with no await in between, so a revocation cannot slip through.
183:     if (!currentConsent()) {
184:       await stopEverything('user').catch(() => undefined);
185:       throw new Error('The camera stays off until you consent.');
186:     }
187:     try {
188:       capture = startCapture({
189:         apiKey,
190:         anchor: meta.startAnchor,
191:         events: {
192:           onSamples: (samples) => ingestSamples(defaultDataRoot(), samples),
193:           onValidation: publishValidation,
194:           onError: publishSdkError,
