206:   });
207:   ipcMain.handle(SESSION_STOP_CHANNEL, async (_event, payload: unknown) => {
208:     const parsed = sessionStopRequestSchema.safeParse(payload ?? {});
209:     if (!parsed.success) throw new Error('Stop does not take any details.');
210:     return stopEverything('user');
211:   });
212:   ipcMain.handle(COACH_GAP_CHANNEL, (_event, payload: unknown) => {
213:     const parsed = coachGapRequestSchema.safeParse(payload);
214:     if (!parsed.success) throw new Error('Mark the game boundary as either between games or playing.');
215:     if (!coach) throw new Error('Start sensing before marking a game boundary.');
216:     const message = coach.setBetweenGames(parsed.data.betweenGames);
217:     if (message) publishToWindows(COACH_MESSAGE_CHANNEL, coachMessageSchema.parse(message));
218:     return parsed.data;
219:   });
