222: function installSessionGuards(): void {
223:   const devUrl = process.env.CHESSPULSE_RENDERER_URL;
224:   const urls = ['file://*'];
225:   let development = false;
226:   if (devUrl) {
227:     try {
228:       urls.push(`${new URL(devUrl).origin}/*`);
229:       development = true;
230:     } catch {
231:       // Navigation already rejects a dev URL that is not a URL.
232:     }
233:   }
234:   const policy = contentSecurityPolicy(development);
235: 
236:   session.defaultSession.webRequest.onHeadersReceived({ urls }, (details, callback) => {
237:     callback({
238:       responseHeaders: {
239:         ...details.responseHeaders,
240:         'Content-Security-Policy': [policy],
241:       },
242:     });
243:   });
244: 
245:   session.defaultSession.setPermissionCheckHandler((_contents, permission, requestingOrigin, details) =>
246:     grantsMediaPermission({
247:       permission,
248:       requestingUrl: details.requestingUrl ?? requestingOrigin,
249:       appFileUrl: appFileUrl(),
250:       devOrigin: rendererDevOrigin(),
251:       consentGranted: currentConsent(),
252:       isMainFrame: details.isMainFrame,
253:       mediaType: details.mediaType,
254:     }),
255:   );
256: 
257:   session.defaultSession.setPermissionRequestHandler((_contents, permission, callback, details) => {
258:     const mediaTypes = 'mediaTypes' in details ? details.mediaTypes : undefined;
259:     callback(
260:       grantsMediaPermission({
261:         permission,
262:         requestingUrl: details.requestingUrl,
263:         appFileUrl: appFileUrl(),
264:         devOrigin: rendererDevOrigin(),
265:         consentGranted: currentConsent(),
266:         isMainFrame: details.isMainFrame,
267:         mediaTypes,
268:       }),
269:     );
270:   });
271: }
