279: function createWindow(): void {
280:   const target = rendererTarget();
281:   const win = new BrowserWindow({
282:     width: 1100,
283:     height: 760,
284:     backgroundColor: '#0E1012',
285:     show: true,
286:     webPreferences: {
287:       preload: path.join(__dirname, '../preload/index.js'),
288:       contextIsolation: true,
289:       sandbox: true,
290:       nodeIntegration: false,
291:       // The player focuses another window to play chess. Throttled frames would starve the
292:       // measurement, so the page must keep its timers and frame callbacks at full rate.
293:       backgroundThrottling: false,
294:     },
295:   });
296: 
297:   win.webContents.setWindowOpenHandler(() => ({ action: 'deny' }));
298:   win.webContents.on('will-navigate', (event, url) => {
299:     if (allowsNavigation(url, process.env.CHESSPULSE_RENDERER_URL)) return;
300:     event.preventDefault();
301:   });
302:   win.webContents.on('did-finish-load', () => {
303:     log('[chesspulse] window-open');
304:   });
305: 
306:   if (target.startsWith('http://') || target.startsWith('https://')) {
307:     void win.loadURL(target);
308:     return;
309:   }
310:   void win.loadFile(target);
311: }
