313: installSafeConsole();
314: 
315: app.whenReady().then(async () => {
316:   const env = loadEnvFile(path.join(app.getAppPath(), '.env'), process.env);
317:   if (env.found && env.loadedKeys.length > 0) {
318:     log(`[chesspulse] loaded ${env.loadedKeys.length} setting(s) from .env`);
319:   }
320:   installSessionGuards();
321:   registerConsentHandler(
322:     { appFileUrl: appFileUrl(), devOrigin: rendererDevOrigin() },
323:     {
324:       onRevoked: () => {
325:         void stopEverything('user').catch(() => undefined);
326:       },
327:     },
328:   );
329:   registerSessionHandlers();
330:   registerPasteHandler();
331:   registerReportHandler();
332:   registerInsightHandler();
333:   setSampleSink(defaultDataRoot(), publishSamples);
334:   try {
335:     const recovery = await recoverInterruptedSessions(defaultDataRoot());
336:     for (const failure of recovery.failures) {
337:       logError(`${failure.id}: ${failure.message}`);
338:     }
339:   } catch (error) {
340:     logError(error instanceof Error ? error.message : 'An open session could not be closed.');
341:   }
342:   createWindow();
343:   app.on('activate', () => {
344:     if (BrowserWindow.getAllWindows().length === 0) createWindow();
345:   });
346: });
