422: function statusLine(
423:   phase: Phase,
424:   samples: PulseSample[],
425:   note: string,
426:   validation: ValidationMessage | null,
427: ): string {
428:   if (phase !== 'sensing') return note;
429:   if (validation && validation.code !== 0) return validation.hint;
430:   if (samples.length === 0) return 'Waiting for a face.';
431:   const latest = samples[samples.length - 1];
432:   if (!latest.stable || latest.confidence < CONFIDENCE_FLOOR) {
433:     return samples.some((sample) => sample.stable && sample.confidence >= CONFIDENCE_FLOOR)
434:       ? 'Low confidence.'
435:       : 'Validating.';
436:   }
437:   return 'Sensing.';
438: }
