440: function stoppedNote(meta: SessionMeta): string {
441:   const baseline = meta.baselineBpm === undefined ? 'No baseline.' : `Baseline ${formatNumber(meta.baselineBpm)} bpm.`;
442:   const coverage = meta.coverage === undefined ? 'No coverage.' : `Coverage ${formatNumber(meta.coverage.pct)}%.`;
443:   return `${baseline} ${coverage}`;
444: }
445: 
446: function formatNumber(value: number): string {
447:   return Number.isInteger(value) ? String(value) : value.toFixed(1);
448: }
