450: /** Electron wraps a rejected invoke in "Error invoking remote method …: Error: ", which is not for the player. */
451: function ipcErrorText(caught: unknown, fallback: string): string {
452:   if (!(caught instanceof Error)) return fallback;
453:   const marker = 'Error: ';
454:   const at = caught.message.lastIndexOf(marker);
455:   const text = (at >= 0 ? caught.message.slice(at + marker.length) : caught.message).trim();
456:   return text.length > 0 && !text.startsWith('Error invoking remote method') ? text : fallback;
457: }

