463: async function closeAfter(handle: AtomicFileHandle, operation: () => Promise<void>): Promise<void> {
464:   let failed = false;
465:   let failure: unknown;
466:   try {
467:     await operation();
468:   } catch (error) {
469:     failed = true;
470:     failure = error;
471:   }
472:   try {
473:     await handle.close();
474:   } catch (error) {
475:     if (!failed) {
476:       failed = true;
477:       failure = error;
478:     }
479:   }
480:   if (failed) throw failure;
481: }
