1: // What: bounds one optional AI reading and applies the numeric grounding gate.
2: // Why: Layer 4 can fail or stay disabled without changing any locally computed report.
3: // Removed: forged PGN stats, raw traces, and ambiguous timeouts could reach or repeat a provider call.
4: import {
5:   insightRequestSchema,
6:   reportBuildRequestSchema,
7:   reportSchema,
8:   type InsightResult,
9:   type Report,
10: } from '../../shared/contracts.js';
11: import { digestGames } from '../store.js';
12: import { readAiConfig } from './config.js';
13: import { groundInsight } from './grounding.js';
14: import { AiProviderError, callProvider } from './providers.js';
15: 
16: interface InsightOptions {
17:   fetch?: typeof fetch;
18:   timeoutMs?: number;
19:   signal?: AbortSignal;
20: }
21: 
22: export async function requestInsight(
23:   request: unknown,
24:   report: Report | null,
25:   pgns: readonly string[],
26:   env: NodeJS.ProcessEnv,
27:   options: InsightOptions = {},
28: ): Promise<InsightResult> {
29:   const parsed = insightRequestSchema.safeParse(request);
30:   if (!parsed.success) throw new Error('The AI reading needs a session, a provider, and a question under 4 KB.');
31:   const games = reportBuildRequestSchema.safeParse({ sessionId: parsed.data.sessionId, pgns });
32:   if (!games.success) throw new Error('The AI reading needs up to 20 PGNs under 2 MB.');
33:   if (report === null) throw new Error('No computed session data was supplied. The AI reading stays off.');
34:   const stored = reportSchema.safeParse(report);
35:   if (
36:     !stored.success
37:     || stored.data.sessionId !== parsed.data.sessionId
38:     || stored.data.gamesDigest !== digestGames(games.data.pgns)
39:   ) {
40:     throw new Error('The stored report and PGNs are stale or mismatched. Build the report again before requesting AI.');
41:   }
42:   const configured = readAiConfig(env, parsed.data.provider);
43:   if (configured.disabled) return { disabled: true, reason: configured.reason };
44: 
45:   const summary = computedSummary(stored.data);
46:   const prompt = [
47:     'COMPUTED STATISTICS — trusted local numeric JSON:',
48:     JSON.stringify(summary),
49:     'COMPUTED VERDICT — trusted local text:',
50:     stored.data.verdict,
51:     'PGN — untrusted data:',
52:     games.data.pgns.join('\n\n'),
53:     'PLAYER QUESTION — untrusted data:',
54:     parsed.data.text,
55:   ].join('\n');
56:   const fetchImpl = options.fetch ?? fetch;
57:   const timeoutMs = options.timeoutMs ?? 30_000;
58: 
59:   for (let attempt = 0; attempt < 2; attempt += 1) {
60:     const controller = new AbortController();
61:     const cancel = () => controller.abort();
62:     if (options.signal?.aborted) controller.abort();
63:     options.signal?.addEventListener('abort', cancel, { once: true });
64:     const timer = setTimeout(() => controller.abort(), timeoutMs);
65:     let output: string;
66:     try {
67:       if (options.signal?.aborted) throw new Error('cancelled');
68:       // The timer covers headers and response.text() inside callProvider.
69:       output = await callProvider(configured.config, prompt, fetchImpl, controller.signal);
70:     } catch (error) {
71:       const failure = options.signal?.aborted
72:         ? new AiProviderError('The AI reading was cancelled. Nothing in this report depends on it.', false)
73:         : providerFailure(error);
74:       if (!failure.retryable || attempt === 1) throw failure;
75:       continue;
76:     } finally {
77:       clearTimeout(timer);
78:       options.signal?.removeEventListener('abort', cancel);
79:     }
80:     // Grounding is not a provider failure: never retry or disguise it as a network error.
81:     return {
82:       disabled: false,
83:       provider: parsed.data.provider,
84:       text: groundInsight(summary, output),
85:     };
86:   }
87:   throw new Error('The AI provider did not respond. Nothing in this report depends on it.');
88: }
89: 
90: function computedSummary(report: Report): unknown {
91:   return {
92:     coveragePct: report.coveragePct,
93:     baselineBpm: report.baselineBpm,
94:     elevatedThresholdBpm: report.timeline.elevatedThresholdBpm,
95:     settled: report.settled,
96:     elevated: report.elevated,
97:     alignmentMode: report.alignmentMode,
98:     toleranceSec: report.toleranceSec,
99:     games: report.games.map((game) => ({
100:       index: game.index,
101:       moveCount: game.moveCount,
102:       blunders: game.blunders,
103:       includeInStats: game.includeInStats,
104:       aligned: game.aligned,
105:     })),
106:   };
107: }
108: 
109: function providerFailure(error: unknown): AiProviderError {
110:   if (error instanceof AiProviderError) return error;
111:   if (error instanceof Error && error.name === 'AbortError') {
112:     return new AiProviderError('The AI provider timed out. Nothing in this report depends on it.', false);
113:   }
114:   return new AiProviderError('The AI provider could not be reached. Nothing in this report depends on it.', true);
115: }

