30:   if (!parsed.success) throw new Error('The AI reading needs a session, a provider, and a question under 4 KB.');
31:   const games = reportBuildRequestSchema.safeParse({ sessionId: parsed.data.sessionId, pgns });
32:   if (!games.success) throw new Error('The AI reading needs up to 20 PGNs under 2 MB.');
33:   if (report === null) throw new Error('No computed session data was supplied. The AI reading stays off.');
34:   const stored = reportSchema.safeParse(report);
35:   if (
36:     !stored.success
37:     || stored.data.sessionId !== parsed.data.sessionId
38:     || stored.data.gamesDigest !== digestGames(games.data.pgns)
39:   ) {
40:     throw new Error('The stored report and PGNs are stale or mismatched. Build the report again before requesting AI.');
41:   }
42:   const configured = readAiConfig(env, parsed.data.provider);
43:   if (configured.disabled) return { disabled: true, reason: configured.reason };
44: 
45:   const summary = computedSummary(stored.data);
46:   const prompt = [
47:     'COMPUTED STATISTICS — trusted local numeric JSON:',
48:     JSON.stringify(summary),
49:     'COMPUTED VERDICT — trusted local text:',
50:     stored.data.verdict,
51:     'PGN — untrusted data:',
52:     games.data.pgns.join('\n\n'),
53:     'PLAYER QUESTION — untrusted data:',
54:     parsed.data.text,
55:   ].join('\n');
56:   const fetchImpl = options.fetch ?? fetch;
57:   const timeoutMs = options.timeoutMs ?? 30_000;
58: 
59:   for (let attempt = 0; attempt < 2; attempt += 1) {
60:     const controller = new AbortController();
61:     const cancel = () => controller.abort();
62:     if (options.signal?.aborted) controller.abort();
63:     options.signal?.addEventListener('abort', cancel, { once: true });
64:     const timer = setTimeout(() => controller.abort(), timeoutMs);
65:     let output: string;
66:     try {
67:       if (options.signal?.aborted) throw new Error('cancelled');
68:       // The timer covers headers and response.text() inside callProvider.
69:       output = await callProvider(configured.config, prompt, fetchImpl, controller.signal);
70:     } catch (error) {
