79:     }
80:     // Grounding is not a provider failure: never retry or disguise it as a network error.
81:     return {
82:       disabled: false,
83:       provider: parsed.data.provider,
84:       text: groundInsight(summary, output),
85:     };
86:   }
87:   throw new Error('The AI provider did not respond. Nothing in this report depends on it.');
88: }
